<script lang="ts">
import BookAccess from './BookAccess.svelte';
import {fade} from 'svelte/transition';
import {works,people,events,date,authorNames,matchesRegion,type Entry} from '../history';
import {participants} from '../../data.js';
import {toYear} from '../../galaxy.js';
let {item,year,select,reduced,pinned=false,focusPeriod='',follow,simultaneousEvents=[]}:{item:Entry;year:number;select:(id:string,jump?:boolean|'start'|'end')=>void;reduced:boolean;pinned?:boolean;focusPeriod?:string;follow:()=>void;simultaneousEvents?:Entry[]}=$props();
let status=$derived(year<toYear(item.start)?'future':year>=toYear(item.end)?'ended':'active');
</script>
<aside id="detail" aria-live="polite"><div class="detail-focus"><span title="自动导览从已发生的事件与文献中按优先级选择，重点至少展示六秒。">{pinned?'已固定当前资料':focusPeriod?`当前重点 · ${focusPeriod}`:'播放时精选本期重点'}</span>{#if pinned}<button onclick={follow}>跟随播放 →</button>{/if}</div>{#if simultaneousEvents.length>1}<details class="concurrent-events"><summary>同期事件 · {simultaneousEvents.length} 项</summary><p>含正在进行及最近一年结束的事件，按导览优先级排列。</p>{#each simultaneousEvents as event}<button class:current={event.id===item.id} onclick={()=>select(event.id)}>{event.name}<small>{event.start} — {event.end}</small></button>{/each}</details>{/if}{#key item.id}<div in:fade={{duration:reduced?0:160}}><p class="eyebrow">{item.type==='work'?'文献档案':item.type==='person'?'人物档案':'历史事件'} / {item.region==='china'?'中国脉络':matchesRegion(item,'soviet')?'苏联脉络':'世界背景'}</p><div class="detail-symbol">{item.type==='work'?'✦':item.type==='person'?'◉':'✧'}</div><h2>{item.name}</h2>
{#if item.type==='work'}<p class="authors">{authorNames(item)}</p><dl class="work-dates"><dt>{item.dateLabel||'写作时间'}</dt><dd><button class="date-jump" title="跳到时间段开始" onclick={()=>select(item.id,'start')}>{date(item.start)}</button>{#if item.start!==item.end} — <button class="date-jump" title="跳到时间段结束" onclick={()=>select(item.id,'end')}>{date(item.end)}</button>{/if}</dd><dt>首次发表 / 版本</dt><dd>{item.published}</dd></dl>{:else}<p class="detail-dates"><button class="date-jump" title={item.type==='person'?'跳到出生时间':'跳到事件开始'} onclick={()=>select(item.id,'start')}>{date(item.start)}</button><br><span>— <button class="date-jump" title={toYear(item.end)>2000?'超出展示范围，跳到 2000 年边界':item.type==='person'?'跳到逝世时间':'跳到事件结束'} onclick={()=>select(item.id,'end')}>{date(item.end)}</button></span></p>{/if}
<div class="status">{status==='future'?'尚未抵达':status==='active'?(item.type==='work'?'写作中':item.type==='person'?'在世':'进行中'):(item.type==='work'?'已抵达文献节点':item.type==='person'?'已逝世':'已结束 / 已完成')}</div><p class="description">{item.description}</p>{#if item.type==='person'&&item.outcome}<section class="person-outcome"><h3>历史结局</h3><p>{item.outcome.summary}</p><a href={item.outcome.source} target="_blank" rel="noopener noreferrer">查阅结局资料 ↗</a></section>{/if}{#if item.type==='person'&&item.assessment}<section class="person-assessment"><h3>党史评价依据</h3><p>{item.assessment.summary}</p><a href={item.assessment.source} target="_blank" rel="noopener noreferrer">{item.assessment.title} ↗</a></section>{/if}{#if item.type==='work'}<BookAccess {item}/>{/if}<a class="source" href={item.source} target="_blank" rel="noopener noreferrer">查阅资料 / 原文 ↗</a>
{#if item.type==='person'}<div class="related"><p>代表文献</p>{#each works.filter(w=>w.authors?.includes(item.id)) as w}<button onclick={()=>select(w.id,true)}>{w.name} <small>{w.end.slice(0,4)}</small></button>{:else}<span>本图谱暂无收录</span>{/each}</div>{/if}{#if item.type==='event'}<div class="related"><p>关联人物（非完整名单）</p>{#each people.filter(p=>((participants as Record<string,string[]>)[item.id]||[]).includes(p.id)) as person}<button onclick={()=>select(person.id)}>{person.name}{#if item.participantRoles?.[person.id]} <small>· {item.participantRoles[person.id]}</small>{/if}</button>{:else}<span>此条按集体历史事件展示，未指定个人轨迹。</span>{/each}</div>{/if}
{#if item.type==='person'}<div class="related"><p>关联事件</p>{#each events.filter(e=>((participants as Record<string,string[]>)[e.id]||[]).includes(item.id)) as e}<button onclick={()=>select(e.id,true)}>{e.name}{#if e.participantRoles?.[item.id]} <small>· {e.participantRoles[item.id]}</small>{/if} <small>{e.start.slice(0,4)}—{e.end.slice(0,4)}</small></button>{:else}<span>本图谱暂无收录</span>{/each}</div>{/if}{#if toYear(item.end)>2000}<p class="detail-note">此条结束日期超出 2000 年展示范围，保留完整日期；跳转定位至 2000 年边界。</p>{/if}<p class="detail-note">{item.type==='work'?'星点优先以写作完成时间定位；出版节点与特殊版本另作说明。':item.type==='person'?'生命区间不等于政治活动区间。':'事件的起止口径见条目说明。'}</p></div>{/key}</aside>
